param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-special-symbols-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Decode($Spec,$Encoded){if([object]::ReferenceEquals($Encoded,$null)){$v=$null}elseif($Spec.kind -eq 'int'){$v=[int]$Encoded}elseif($Spec.kind -eq 'array'){$v=[int[]]$Encoded}else{$v=-join [char[]][int[]]$Encoded};return ,$v}
function New-Seed{$n=[Globalization.NumberFormatInfo]::new();foreach($spec in $plan.properties){[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($n,(Decode $spec $spec.seed))};return $n}
function Snapshot($N){$values=[ordered]@{};foreach($spec in $plan.properties){$v=[Globalization.NumberFormatInfo].GetProperty($spec.name).GetValue($N);if($spec.kind -eq 'string'){$values[$spec.name]=[int[]][char[]]$v}elseif($spec.kind -eq 'array'){$values[$spec.name]=[int[]]$v}else{$values[$spec.name]=[int]$v}};return [ordered]@{readOnly=$N.IsReadOnly;values=$values}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null})}}

$defaults=Snapshot ([Globalization.NumberFormatInfo]::new());$invariantBefore=Snapshot ([Globalization.NumberFormatInfo]::InvariantInfo);$rows=[Collections.Generic.List[object]]::new()
foreach($spec in $plan.properties){if($spec.name -notin $plan.specialProperties){continue};for($profileIndex=0;$profileIndex -lt $spec.inputs.Count;$profileIndex++){foreach($mode in @('mutable','readonly','clone','invariant')){$original=New-Seed;$ro=[Globalization.NumberFormatInfo]::ReadOnly($original);switch($mode){'mutable'{$target=$original};'readonly'{$target=$ro};'clone'{$target=[Globalization.NumberFormatInfo]$ro.Clone()};'invariant'{$target=[Globalization.NumberFormatInfo]::InvariantInfo}};$before=Snapshot $target;try{[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($target,(Decode $spec $spec.inputs[$profileIndex]));$result=[ordered]@{ok=$true}}catch{$result=Failure $_};$rows.Add([ordered]@{property=$spec.name;profile=$profileIndex;mode=$mode;before=$before;result=$result;after=(Snapshot $target);originalAfter=(Snapshot $original)})}}}
if($rows.Count -ne 108){throw 'Wrong special-symbol matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';defaults=$defaults;invariantBefore=$invariantBefore;rows=$rows.ToArray();invariantAfter=(Snapshot ([Globalization.NumberFormatInfo]::InvariantInfo));qualification='REPRESENTED_NUMBERFORMATINFO_SPECIAL_SYMBOL_STATE_25_FIELDS_ONLY; FLOAT_FORMATTING_OTHER_CULTURES_FULL_METADATA_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 24 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS special symbols: 25 represented fields, 108 cases'
